tests.code:
// Intercepta listagem de quartos
cy.intercept('GET', '/api/quartos', {
  fixture: 'rooms.json'
}).as('getQuartos');
cy.visit('/');
cy.wait('@getQuartos');
cy.contains('Quarto Luxo').should('be.visible');
// Seleciona um quarto
cy.contains('Selecionar').first().click();
// Preenche dados
cy.get('input[placeholder="Nome"]').type('Cliente Teste');
cy.get('input[placeholder="Email"]').type('cliente@teste.com');
cy.get('input[type="date"]').first().type('2025-11-01');
cy.get('input[type="date"]').eq(1).type('2025-11-03');
cy.get('input[placeholder="Hóspedes"]').type('2');
// Intercepta disponibilidade
cy.intercept('GET', '/api/disponibilidade*', {
  statusCode: 200,
  body: {
    availableRooms: [{
      id: 101
    }, {
      id: 202
    }]
  }
}).as('getDisp');
// Checa disponibilidade
cy.contains('Checar disponibilidade').click();
cy.wait('@getDisp');
cy.contains('Quarto selecionado está disponível').should('be.visible');
// Intercepta criação de reserva
cy.intercept('POST', '/api/reservas', {
  statusCode: 200,
  body: {
    id: 123,
    total: 350
  }
}).as('postReserva');
// Intercepta PIX
cy.intercept('POST', '/api/pagamento/pix', {
  statusCode: 200,
  body: {
    qr_code_base64: 'iVBORw0KGgoAAAAN',
    qr_code: '000201010212'
  }
}).as('postPix');
// Reserva
cy.contains('Reservar').click();
cy.wait('@postReserva');
cy.contains('Reserva criada! ID 123').should('be.visible');
// PIX exibido
cy.contains('Pague com PIX').should('be.visible');
cy.contains('Copia e Cola:').should('be.visible');

// Seleciona primeiro quarto
cy.get('[data-cy="room-card"]').should('have.length', 2);
cy.get('[data-cy="select-room"]').first().click();
// Preenche dados
cy.get('[data-cy="input-name"]').type('Cliente Teste');
cy.get('[data-cy="input-email"]').type('cliente@teste.com');
cy.get('[data-cy="input-checkin"]').type('2024-12-01');
cy.get('[data-cy="input-checkout"]').type('2024-12-03');
cy.get('[data-cy="input-guests"]').clear().type('2');
// Nenhuma disponibilidade
cy.intercept('GET', '/api/disponibilidade*', {
  statusCode: 200,
  body: {
    availableRooms: []
  }
}).as('getDisp');
cy.get('[data-cy="check-availability"]').click();
cy.wait('@getDisp');
// Deve exibir erro e desabilitar reservar
cy.get('[data-cy="status-message"]').should('contain', 'não está disponível');
cy.get('[data-cy="reserve"]').should('be.disabled');

// Seleciona primeiro quarto
cy.get('[data-cy="select-room"]').first().click();
// Preenche dados
cy.get('[data-cy="input-name"]').type('Cliente Teste');
cy.get('[data-cy="input-email"]').type('cliente@teste.com');
cy.get('[data-cy="input-checkin"]').type('2024-12-01');
cy.get('[data-cy="input-checkout"]').type('2024-12-03');
cy.get('[data-cy="input-guests"]').clear().type('2');
// Disponibilidade positiva para o quarto selecionado
cy.intercept('GET', '/api/disponibilidade*', {
  statusCode: 200,
  body: {
    availableRooms: [{
      id: 101
    }]
  }
}).as('getDispOk');
cy.get('[data-cy="check-availability"]').click();
cy.wait('@getDispOk');
// Reserva falha
cy.intercept('POST', '/api/reservas', {
  statusCode: 500,
  body: {
    error: 'Falha ao criar reserva'
  }
}).as('postReservaFail');
cy.get('[data-cy="reserve"]').click();
cy.wait('@postReservaFail');
cy.get('[data-cy="status-message"]').should('contain', 'Falha ao criar reserva');

// Seleciona primeiro quarto
cy.get('[data-cy="select-room"]').first().click();
// Preenche dados
cy.get('[data-cy="input-name"]').type('Cliente Teste');
cy.get('[data-cy="input-email"]').type('cliente@teste.com');
cy.get('[data-cy="input-checkin"]').type('2024-12-05');
cy.get('[data-cy="input-checkout"]').type('2024-12-07');
cy.get('[data-cy="input-guests"]').clear().type('2');
// Disponibilidade positiva para o quarto selecionado
cy.intercept('GET', '/api/disponibilidade*', {
  statusCode: 200,
  body: {
    availableRooms: [{
      id: 101
    }]
  }
}).as('getDispOk2');
cy.get('[data-cy="check-availability"]').click();
cy.wait('@getDispOk2');
// Reserva OK
cy.intercept('POST', '/api/reservas', {
  statusCode: 200,
  body: {
    id: 999,
    total: 350
  }
}).as('postReservaOk');
// PIX falha
cy.intercept('POST', '/api/pagamento/pix', {
  statusCode: 500,
  body: {
    error: 'Falha ao gerar PIX'
  }
}).as('postPixFail');
cy.get('[data-cy="reserve"]').click();
cy.wait('@postReservaOk');
cy.wait('@postPixFail');
cy.get('[data-cy="status-message"]').should('contain', 'Falha ao gerar PIX');

